"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[11333],{48439:n=>{n.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainAnimController","desc":"Plays the Aureline locomotive and flatcar animations from game state. Every\\nclient plays its own tracks on each rig\'s `AnimationController.Animator`;\\nnothing replicates.\\n\\nState comes from `Signals.OnTrainStateChanged` / `TrainStateCache` (brake,\\nstall), `Signals.OnTrainShieldChanged` / `TrainStateCache` (shield),\\n`Packets.JumpStateSync` (jump phase) and the jump drive bench\'s\\n`ChargingBy` attribute (chute). `TrainAnimRules` turns it into one value per\\nchannel; this script diffs each rig\'s last values and plays only the\\ntransitions. A rig\'s first values (join, stream-in, a car built mid-run)\\nsnap: held clips jump to their last frame, a jump in progress starts at\\nJumpLoop, and no transition clip plays. Clip ids, loop and priority are in\\n`TrainAnimConfig`.","realm":["Client"],"source":{"line":20,"path":"src/StarterPlayer/StarterPlayerScripts/TrainAnimController.client.luau"}}')}}]);